package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }







    @Test
    public void testEscape_WithEntityNames() {
        // Tests the branch: entityName != null
        // Assuming standard HTML entities like '<' -> "&lt;"
        // We use addEntity to ensure predictable behavior for the test
        entities.addEntity("lt", '<');
        entities.addEntity("gt", '>');
        entities.addEntity("amp", '&');

        assertEquals("&lt;", entities.escape("<"));
        assertEquals("&gt;", entities.escape(">"));
        assertEquals("&amp;", entities.escape("&"));
        assertEquals("&lt;a&gt;", entities.escape("<a>"));
    }








}

