public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }









    @Test
    public void testEscape_WithHighAscii() {
        // Tests the branch: entityName == null && ch > 0x7F
        // Character 0x80 (128)
        assertEquals("&#128;", entities.escape("\u0080"));
        // Character 0xFF (255)
        assertEquals("&#255;", entities.escape("\u00FF"));
    }






}

