import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }











    @Test
    public void testEscape_MixedContent() {
        // Comprehensive test covering all branches in one string
        entities.addEntity("quot", '"');

        // 1. Normal char: 'a'
        // 2. Entity char: '"'
        // 3. High char: '\u0080'
        // 4. Normal char: 'z'
        String input = "a\"\u0080z";
        String expected = "a&quot;&#128;z";

        assertEquals(expected, entities.escape(input));
    }




}

