package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }















    @Test
    public void testEscape_NonEntityHighAscii() {
        // Ensure that if a high char is not in entity list, it uses numeric reference
        // Using a character that is definitely not a standard entity
        char highChar = '\u1234'; 
        String input = String.valueOf(highChar);
        assertEquals("&#4660;", entities.escape(input)); // 0x1234 is 4660
    }
}
